// What /usage-plus shows, computed from the files the mod and the indexer keep. Pure.

import type { BustEvent, CompactMark, DashData, DayAgg, DayRow, DistillEvent, DistillSummary, LimitsHistory, MeasureSnapshot, RequestRecord, Share, Tokens, TurnRow } from '../types'

export type { DashData, DayRow, DistillSummary, LimitsHistory, Share, TurnRow }
import { bustCause, cacheHit, costOf, ctxOf, elsewhereShare, isBust, savings, timeable, tokPerSec } from './metrics.ts'
import type { Prev } from './metrics.ts'
import { dayKey, TZ_OFFSET_MIN } from './paths.ts'

const DAY_MS = 86_400_000
const FIVE_H_MS = 5 * 3_600_000
const WEEK_MS = 7 * DAY_MS

export const totalOf = (t: { input: number; output: number; cacheRead: number; cacheWrite: number }) =>
  t.input + t.output + t.cacheRead + t.cacheWrite

/** `n` dates ending at `today`, oldest first. */
export function lastDates(today: string, n: number): string[] {
  const [y, m, d] = today.split('-').map(Number) as [number, number, number]
  const base = Date.UTC(y, m - 1, d)
  return Array.from({ length: n }, (_, i) => new Date(base - (n - 1 - i) * DAY_MS).toISOString().slice(0, 10))
}

function sumModels(day: DayAgg, f: (t: Tokens, model: string) => number | undefined): number {
  return Object.entries(day.byModel).reduce((n, [model, t]) => n + (f(t, model) ?? 0), 0)
}

export function dayRows(days: readonly DayAgg[], dates: readonly string[]): DayRow[] {
  const byDate = new Map(days.map(d => [d.date, d]))
  return dates.map(date => {
    const d = byDate.get(date)
    if (!d) return { date, read: 0, write: 0, input: 0, output: 0, cost: 0, savings: 0, requests: 0 }
    const t = d.total
    const row: DayRow = {
      date,
      read: t.cacheRead,
      write: t.cacheWrite,
      input: t.input,
      output: t.output,
      cost: t.costUsd,
      savings: sumModels(d, (tok, model) => savings(tok, model)),
      requests: d.requests,
    }
    const hit = cacheHit(t)
    if (hit !== undefined) row.hit = hit
    return row
  })
}

export function shares(days: readonly DayAgg[], key: 'byModel' | 'byProject', top = 4, short = (s: string) => s): Share[] {
  const sums = new Map<string, number>()
  for (const d of days) {
    for (const [name, t] of Object.entries(d[key])) sums.set(short(name), (sums.get(short(name)) ?? 0) + totalOf(t))
  }
  const all = [...sums.values()].reduce((a, b) => a + b, 0)
  const sorted = [...sums.entries()].sort((a, b) => b[1] - a[1])
  const head = sorted.slice(0, top).map(([name, tokens]) => ({ name, tokens, share: all > 0 ? tokens / all : 0 }))
  const rest = sorted.slice(top).reduce((n, [, t]) => n + t, 0)
  if (rest > 0) head.push({ name: 'khác', tokens: rest, share: rest / all })
  return head
}

/** The session's main-loop turns, oldest first. */
export function sessionTurns(records: readonly RequestRecord[]): TurnRow[] {
  const rows: TurnRow[] = []
  const byTurn = new Map<string, RequestRecord[]>()
  for (const r of records) {
    if (r.isSubagent) continue
    const id = r.turnId ?? `@${r.ts}`
    if (!byTurn.has(id)) byTurn.set(id, [])
    byTurn.get(id)?.push(r)
  }
  let prevCtx: number | undefined
  for (const [turnId, rs] of byTurn) {
    const sum = rs.reduce(
      (t, r) => ({ input: t.input + r.input, output: t.output + r.output, cacheRead: t.cacheRead + r.cacheRead, cacheWrite: t.cacheWrite + r.cacheWrite }),
      { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
    )
    const last = rs[rs.length - 1] as RequestRecord
    const ctx = ctxOf(last)
    const row: TurnRow = {
      turnId,
      ts: (rs[0] as RequestRecord).ts,
      requests: rs.length,
      ctx,
      cost: rs.reduce((n, r) => n + (costOf(r, r.model) ?? 0), 0),
    }
    const hit = cacheHit(sum)
    if (hit !== undefined) row.hit = hit
    const timed = rs.filter(r => timeable(r.output, r.durationMs))
    const tps = tokPerSec(timed.reduce((n, r) => n + r.output, 0), timed.reduce((n, r) => n + (r.durationMs as number), 0))
    if (tps !== undefined) row.tps = tps
    if (prevCtx !== undefined) row.delta = ctx - prevCtx
    prevCtx = ctx
    rows.push(row)
  }
  return rows
}

/** Busts among a session's live requests (no 5m/1h split: the live TTL default). */
export function sessionBusts(records: readonly RequestRecord[], marks: readonly CompactMark[]): BustEvent[] {
  const out: BustEvent[] = []
  let prev: (Prev & { ts: number }) | undefined
  for (const r of records) {
    if (r.isSubagent) continue
    if (prev && isBust(r, prev)) {
      const p = prev
      const compactBetween = marks.some(m => m.sessionId === r.sessionId && m.ts >= p.ts && m.ts <= r.ts)
      out.push({
        ts: r.ts,
        sessionId: r.sessionId,
        project: r.project,
        model: r.model,
        prevModel: p.model,
        gapMs: r.ts - p.ts,
        ctx: ctxOf(r),
        cacheRead: r.cacheRead,
        cause: bustCause(r, p, compactBetween),
      })
    }
    prev = { ts: r.ts, model: r.model }
  }
  return out
}

function windowsOf(snaps: readonly MeasureSnapshot[]): Map<number, MeasureSnapshot[]> {
  const out = new Map<number, MeasureSnapshot[]>()
  for (const s of snaps) {
    if (s.resetsAt5h === undefined) continue
    const key = Math.round(s.resetsAt5h / 60_000) * 60_000
    if (!out.has(key)) out.set(key, [])
    out.get(key)?.push(s)
  }
  return out
}

export function limitsHistory(snaps: readonly MeasureSnapshot[], records: readonly RequestRecord[], now: number, dates: readonly string[]): LimitsHistory {
  const out: LimitsHistory = { five: [], week: [] }
  const windows = [...windowsOf(snaps).entries()].sort((a, b) => a[0] - b[0])
  const peaks = windows.map(([reset, ss]) => {
    const top = ss.reduce((a, b) => (b.fiveHourPct > a.fiveHourPct ? b : a))
    return { reset, pct: top.fiveHourPct, ts: top.ts }
  })
  out.five = peaks.slice(-7).map(p => p.pct)
  const peak = peaks.slice(-7).reduce<(typeof peaks)[number] | undefined>((a, b) => (a === undefined || b.pct > a.pct ? b : a), undefined)
  if (peak) out.fivePeak = { pct: peak.pct, ts: peak.ts }

  out.week = dates.map(date => {
    const ss = snaps.filter(s => dayKey(s.ts, TZ_OFFSET_MIN) === date)
    return ss.length > 0 ? Math.max(...ss.map(s => s.weekPct)) : undefined
  })
  const last = snaps[snaps.length - 1]
  if (last) {
    out.weekNow = last.weekPct
    if (last.resetsAtWeek !== undefined) {
      const elapsed = last.ts - (last.resetsAtWeek - WEEK_MS)
      if (elapsed > 6 * 3_600_000) out.weekForecast = Math.round((last.weekPct / elapsed) * WEEK_MS)
    }
  }

  // Usage elsewhere: each 5-hour window's peak against what this machine spent in it.
  const costIn = (from: number, to: number) =>
    records.filter(r => r.ts >= from && r.ts < to).reduce((n, r) => n + (costOf(r, r.model) ?? 0), 0)
  const done = peaks.filter(p => p.reset <= now).map(p => ({ pctUsed: p.pct, localCost: costIn(p.reset - FIVE_H_MS, p.reset) }))
  const current = peaks.find(p => p.reset > now)
  if (current) {
    const share = elsewhereShare(done, { pctUsed: current.pct, localCost: costIn(current.reset - FIVE_H_MS, now) })
    if (share !== undefined) out.elsewhere = share
  }
  return out
}

export function distillSummary(events: readonly DistillEvent[]): DistillSummary {
  const byKind = new Map<string, { kind: string; n: number; cut: number }>()
  let cut = 0
  let reread = 0
  for (const e of events) {
    const c = Math.max(0, e.rawChars - e.outChars)
    cut += c
    if (e.reread) reread++
    const k = byKind.get(e.kind) ?? { kind: e.kind, n: 0, cut: 0 }
    k.n++
    k.cut += c
    byKind.set(e.kind, k)
  }
  return { count: events.length, cut, reread, byKind: [...byKind.values()].sort((a, b) => b.cut - a.cut) }
}

export type DashInput = {
  now: number
  sessionId: string
  days: DayAgg[]
  ledger: RequestRecord[]
  marks: CompactMark[]
  snaps: MeasureSnapshot[]
  distill: DistillEvent[]
  shortModel: (m: string) => string
  indexer?: { newLines: number; bad: number } | { error: string }
}

export function buildDash(i: DashInput): DashData {
  const today = dayKey(i.now, TZ_OFFSET_MIN)
  const dates35 = lastDates(today, 35)
  const week = new Set(dates35.slice(-7))
  const month = new Set(dates35.slice(-30))
  const weekDays = i.days.filter(d => week.has(d.date))
  const monthDays = i.days.filter(d => month.has(d.date))
  const mine = i.ledger.filter(r => r.sessionId === i.sessionId).sort((a, b) => a.ts - b.ts)
  const inWeek = (ts: number) => week.has(dayKey(ts, TZ_OFFSET_MIN))
  const inMonth = (ts: number) => month.has(dayKey(ts, TZ_OFFSET_MIN))

  const data: DashData = {
    builtAt: i.now,
    sessionId: i.sessionId,
    days: dayRows(i.days, dates35),
    week: { byModel: shares(weekDays, 'byModel', 3, i.shortModel), byProject: shares(weekDays, 'byProject', 3) },
    month: { byModel: shares(monthDays, 'byModel', 3, i.shortModel), byProject: shares(monthDays, 'byProject', 3) },
    busts: weekDays
      .flatMap(d => d.busts)
      .sort((a, b) => b.ts - a.ts)
      .slice(0, 5),
    session: { turns: sessionTurns(mine), busts: sessionBusts(mine, i.marks) },
    limits: limitsHistory(i.snaps, i.ledger, i.now, dates35.slice(-7)),
    distillWeek: distillSummary(i.distill.filter(e => inWeek(e.ts))),
    distillMonth: distillSummary(i.distill.filter(e => inMonth(e.ts))),
  }
  if (i.indexer && 'error' in i.indexer) data.indexerError = i.indexer.error
  else if (i.indexer && i.indexer.newLines > 0) data.badShare = i.indexer.bad / i.indexer.newLines
  return data
}

files.hooks/dashboard.ts:
// /usage-plus as lines of coloured segments, per tab and width. Pure: the render hook turns
// each segment into a Text and adds the tab buttons.

import type { BustEvent } from '../types'
import { cacheColor, fmtTokens, fmtTps, shortModel, tpsColor } from './band.ts'
import { columns, fit, hbar, spark, stacked } from './charts.ts'
import type { DashData, DayRow, DistillSummary, Share } from './dashdata.ts'
import { local } from './paths.ts'
import { TZ_OFFSET_MIN } from './paths.ts'
import type { Segment } from './limits.ts'
import { width } from './limits.ts'

export type Tab = 'session' | 'week' | 'month'
export type Line = Segment[]

export const COLORS = { read: 'green', write: 'yellow', input: 'blue', output: 'magenta' } as const
const WEEKDAYS = ['CN', 'T2', 'T3', 'T4', 'T5', 'T6', 'T7']

const dim = (text: string): Segment => ({ text, dim: true })
const plain = (text: string): Segment => ({ text })
const blank: Line = []
const rule = (cols: number): Line => [dim('─'.repeat(Math.max(0, cols)))]

export function usd(n: number): string {
  const a = Math.abs(n)
  const s = a >= 100 ? a.toFixed(0) : a.toFixed(2)
  return `${n < 0 ? '-' : ''}$${s}`
}

function weekdayOf(date: string): string {
  const [y, m, d] = date.split('-').map(Number) as [number, number, number]
  return `${WEEKDAYS[new Date(Date.UTC(y, m - 1, d)).getUTCDay()]} ${String(d).padStart(2, '0')}`
}

function clock(ts: number, withDay = true): string {
  const t = local(ts, TZ_OFFSET_MIN)
  const day = WEEKDAYS[new Date(ts + TZ_OFFSET_MIN * 60_000).getUTCDay()]
  return `${withDay ? `${day} ` : ''}${t.hh}:${t.mm}`
}

const totalOf = (r: DayRow) => r.read + r.write + r.input + r.output
const pct = (x: number) => `${Math.round(x * 100)}%`

function hitOf(rows: readonly DayRow[]): number | undefined {
  const read = rows.reduce((n, r) => n + r.read, 0)
  const ctx = rows.reduce((n, r) => n + r.read + r.write + r.input, 0)
  return ctx > 0 ? read / ctx : undefined
}

function legend(): Line {
  return [
    dim('Tokens / ngày   '),
    { text: '█', color: COLORS.read },
    dim(' cache read  '),
    { text: '█', color: COLORS.write },
    dim(' cache write  '),
    { text: '█', color: COLORS.input },
    dim(' input  '),
    { text: '█', color: COLORS.output },
    dim(' output'),
  ]
}

function barRows(rows: readonly { label: string; row: DayRow }[], cols: number): Line[] {
  const max = Math.max(1, ...rows.map(r => totalOf(r.row)))
  const labelW = Math.max(...rows.map(r => r.label.length))
  const cells = Math.max(4, cols - labelW - 11)
  return rows.map(({ label, row }) => {
    const n = totalOf(row)
    const bar = stacked(
      [
        { value: row.read, color: COLORS.read },
        { value: row.write, color: COLORS.write },
        { value: row.input, color: COLORS.input },
        { value: row.output, color: COLORS.output },
      ],
      Math.round((n / max) * cells),
    )
    if (n === 0) return [plain('  '), dim(label.padEnd(labelW + 2)), dim('·')]
    return [plain('  '), dim(label.padEnd(labelW + 2)), ...bar, plain(' '.repeat(cells - width(bar) + 1)), plain(fmtTokens(n).padStart(6))]
  })
}

function hitLine(rows: readonly DayRow[], label: string): Line {
  const hit = hitOf(rows)
  const saved = rows.reduce((n, r) => n + r.savings, 0)
  const line: Line = [dim('Cache hit  ')]
  if (hit !== undefined) line.push({ text: pct(hit), color: cacheColor(hit * 100) }, dim(` (${label})  `))
  line.push({ text: spark(rows.map(r => r.hit), 1), color: 'green' })
  if (saved !== 0) line.push(dim('   tiết kiệm ≈ '), { text: usd(saved), color: saved >= 0 ? 'green' : 'red' }, dim(' so với không cache'))
  return line
}

export function bustLabel(b: BustEvent): string {
  switch (b.cause) {
    case 'compact':
      return 'sau /compact'
    case 'ttl':
      return `nghỉ ${Math.round((b.gapMs ?? 0) / 60_000)} phút (TTL hết)`
    case 'model_switch':
      return `đổi model ${shortModel(b.prevModel ?? '?')} → ${shortModel(b.model)}`
    default:
      return 'không rõ (prompt/tool đổi?)'
  }
}

function bustColor(b: BustEvent): string | undefined {
  if (b.cause === 'compact' || b.cause === 'ttl') return 'red'
  if (b.cause === 'model_switch') return 'yellow'
  return undefined
}

function bustLines(busts: readonly BustEvent[], title: string, cols: number, withDay = true): Line[] {
  if (busts.length === 0) return [[dim(`${title}: không có`)]]
  const labelW = Math.max(16, cols - 32)
  const out: Line[] = [[dim(`${title.padEnd(labelW + 13)}  ctx  đọc cache`)]]
  for (const b of busts) {
    const color = bustColor(b)
    out.push([
      color ? { text: '●', color } : dim('●'),
      plain(` ${clock(b.ts, withDay).padEnd(withDay ? 9 : 5)}  `),
      ...fit([plain(bustLabel(b))], labelW),
      plain(fmtTokens(b.ctx).padStart(6)),
      plain(fmtTokens(b.cacheRead).padStart(10)),
    ])
  }
  return out
}

function shareLines(title: string, list: readonly Share[], w: number): Line[] {
  const out: Line[] = [[dim(title[0]!.toUpperCase() + title.slice(1))]]
  const nameW = Math.min(10, Math.max(4, ...list.map(s => s.name.length)))
  const cells = Math.max(3, Math.min(6, w - nameW - 7))
  for (const s of list) {
    out.push([plain(s.name.slice(0, nameW).padEnd(nameW + 1)), ...hbar(s.share * 100, cells, 'cyan'), plain(` ${pct(s.share).padStart(4)}`)])
  }
  if (list.length === 0) out.push([dim('chưa có dữ liệu')])
  return out
}

function limitLines(d: DashData): Line[] {
  const l = d.limits
  const out: Line[] = [[dim('Hạn mức (lịch sử)')]]
  if (l.five.length > 0) {
    const line: Line = [dim('5h '), { text: spark(l.five, 100), color: 'yellow' }]
    if (l.fivePeak) line.push(dim(` đỉnh ${Math.round(l.fivePeak.pct)}% ${clock(l.fivePeak.ts).split(' ')[0]}`))
    out.push(line)
  }
  if (l.week.some(v => v !== undefined)) {
    const line: Line = [dim('wk '), { text: spark(l.week, 100), color: 'yellow' }]
    if (l.weekNow !== undefined) line.push(plain(` ${Math.round(l.weekNow)}%`))
    if (l.weekForecast !== undefined) line.push(dim(' → dự báo '), { text: `${l.weekForecast}%`, color: l.weekForecast >= 100 ? 'red' : 'yellow' })
    out.push(line)
  }
  if (l.elsewhere !== undefined) out.push([dim('ngoài máy này ≈ '), plain(pct(l.elsewhere))])
  if (out.length === 1) out.push([dim('chưa có lần đọc nào')])
  return out
}

function distillLines(s: DistillSummary): Line[] {
  if (s.count === 0) return [[dim('Distiller  chưa chưng cất lần nào')]]
  return [
    [
      dim('Distiller  '),
      plain(`${s.count} lần · -${fmtTokens(s.cut)} ký tự · đọc lại ${s.reread}/${s.count} (${pct(s.reread / s.count)})`),
    ],
    s.byKind.flatMap((k, i) => [...(i > 0 ? [plain('  ')] : []), dim(`${k.kind} `), plain(`-${fmtTokens(k.cut)}`)]),
  ]
}

/** The three side columns, or stacked under 80 columns. */
function sideBySide(d: DashData, byModel: Share[], byProject: Share[], cols: number): Line[] {
  const a = shareLines('theo model', byModel, 20)
  const b = shareLines('theo project', byProject, 24)
  const c = limitLines(d)
  if (cols < 80) return [...a, blank, ...b, blank, ...c]
  const w = Math.floor((cols - 4) / 3)
  return columns([a, b, c], [w - 2, w + 1, cols - 4 - (w - 2) - (w + 1)])
}

function summaryOnly(rows: readonly DayRow[], label: string): Line[] {
  const n = rows.reduce((t, r) => t + totalOf(r), 0)
  const cost = rows.reduce((t, r) => t + r.cost, 0)
  const hit = hitOf(rows)
  return [
    [dim(`${label}: `), plain(`${fmtTokens(n)} token · ~${usd(cost)} API-equiv`)],
    hit === undefined ? [dim('cache hit: -')] : [dim('cache hit: '), { text: pct(hit), color: cacheColor(hit * 100) }],
  ]
}

function notices(d: DashData): Line[] {
  const out: Line[] = []
  if (d.indexerError) out.push([{ text: `! indexer: ${d.indexerError}`, color: 'yellow' }])
  if (d.badShare !== undefined && d.badShare > 0.01) out.push([{ text: `! JSONL: ${pct(d.badShare)} dòng không đọc được`, color: 'yellow' }])
  return out
}

function weekTab(d: DashData, cols: number): Line[] {
  const rows = d.days.slice(-7)
  if (cols < 60) return [...notices(d), ...summaryOnly(rows, '7 ngày')]
  return [
    ...notices(d),
    legend(),
    blank,
    ...barRows(rows.map(r => ({ label: weekdayOf(r.date), row: r })), cols),
    blank,
    hitLine(rows, 'tuần'),
    ...bustLines(d.busts, 'Cache bust gần đây', cols),
    blank,
    rule(cols),
    ...sideBySide(d, d.week.byModel, d.week.byProject, cols),
    blank,
    rule(cols),
    ...distillLines(d.distillWeek),
  ]
}

function monthTab(d: DashData, cols: number): Line[] {
  const rows = d.days.slice(-30)
  if (cols < 60) return [...notices(d), ...summaryOnly(rows, '30 ngày')]
  // Weeks of the month, Monday first; the first may be partial.
  const weeks: { label: string; row: DayRow }[] = []
  for (const r of rows) {
    const [y, m, dd] = r.date.split('-').map(Number) as [number, number, number]
    const isMonday = new Date(Date.UTC(y, m - 1, dd)).getUTCDay() === 1
    const last = weeks[weeks.length - 1]
    if (!last || isMonday) {
      weeks.push({ label: `từ ${String(dd).padStart(2, '0')}/${String(m).padStart(2, '0')}`, row: { ...r } })
    } else {
      const w = last.row
      last.row = {
        ...w,
        read: w.read + r.read,
        write: w.write + r.write,
        input: w.input + r.input,
        output: w.output + r.output,
        cost: w.cost + r.cost,
        savings: w.savings + r.savings,
        requests: w.requests + r.requests,
      }
    }
  }
  return [
    ...notices(d),
    legend(),
    blank,
    ...barRows(weeks, cols),
    blank,
    [dim('Theo ngày  '), { text: spark(rows.map(totalOf)), color: 'cyan' }],
    hitLine(rows, 'tháng'),
    blank,
    rule(cols),
    ...sideBySide(d, d.month.byModel, d.month.byProject, cols),
    blank,
    rule(cols),
    ...distillLines(d.distillMonth),
  ]
}

function sessionTab(d: DashData, cols: number): Line[] {
  const turns = d.session.turns
  if (turns.length === 0) return [[dim('Phiên này chưa có turn nào được ghi (ledger bắt đầu từ khi mod chạy).')]]
  const total = turns.reduce((n, t) => n + t.cost, 0)
  const head: Line = [dim(`phiên này · ${turns.length} turn · ~${usd(total)} API-equiv`)]
  if (cols < 60) return [head, ...summaryOnly(d.days.slice(-1), 'hôm nay')]
  const table: Line[] = [[dim('lúc    req  cache    Δctx   chi phí  tok/s')]]
  for (const t of turns.slice(-10)) {
    table.push([
      plain(clock(t.ts, false).padEnd(6)),
      plain(String(t.requests).padStart(4)),
      t.hit === undefined ? plain('      -') : { text: pct(t.hit).padStart(7), color: cacheColor(t.hit * 100) },
      plain((t.delta === undefined ? '-' : `${t.delta >= 0 ? '+' : '-'}${fmtTokens(Math.abs(t.delta))}`).padStart(8)),
      plain(`~${usd(t.cost)}`.padStart(10)),
      t.tps === undefined ? plain('      -') : { text: fmtTps(t.tps).padStart(7), color: tpsColor(t.tps) },
    ])
  }
  const top = [...turns].sort((a, b) => b.cost - a.cost).slice(0, 3)
  const topLine: Line = [dim('tốn nhất: '), plain(top.map(t => `${clock(t.ts, false)} ~${usd(t.cost)}`).join(' · '))]
  return [head, blank, ...table, blank, topLine, blank, ...bustLines(d.session.busts, 'Cache bust trong phiên', cols, false)]
}

/** Every line of a tab, none wider than `cols`. */
export function dashboardLines(d: DashData, tab: Tab, cols: number): Line[] {
  const lines = tab === 'session' ? sessionTab(d, cols) : tab === 'week' ? weekTab(d, cols) : monthTab(d, cols)
  return lines.map(l => (width(l) > cols ? fit(l, cols) : l))
}

export const SUBTITLE: Record<Tab, string> = {
  session: 'phiên hiện tại · tz +07',
  week: '7 ngày qua · tz +07',
  month: '30 ngày qua · tz +07',
}

